INSERT INTO breath_manager_v5.bm5_safety (safety_id, title, description, related_catalog_ids, source_passage_ids) VALUES ('S001', '第5部 共通の実践条件', '{"stop":["苦しさが出る","めまいが出る"],"do_not":["息止めを無理に入れる","強い呼吸を長く続ける","食後すぐに強い呼吸をする","疲労・病気・急性ストレス時に無理に実践する"],"consult":["慢性疾患","痛み","心臓の問題","妊娠中","月経中"],"scope":"原稿に記載された教育上の共通方針。医学的な網羅性・個別適用は未審査。"}', '{}', ARRAY['P23','P29']::text[]) ON CONFLICT (safety_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_safety (safety_id, title, description, related_catalog_ids, source_passage_ids) VALUES ('S002', '第2部 共通の実践条件', '{"stop":["めまい","息苦しさが増す","強い動悸","胸の痛み","不安やパニックが増す"],"do_not":["苦しさを我慢する","秒数を無理に合わせる"],"consult":["高血圧","心臓病","呼吸器疾患","妊娠中","睡眠時無呼吸の指摘","強い日中の眠気"],"scope":"第2部に記載。全実践の禁忌を網羅するものではない。"}', '{}', ARRAY['P055','P174','P177','P187','P199','P209']::text[]) ON CONFLICT (safety_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_safety (safety_id, title, description, related_catalog_ids, source_passage_ids) VALUES ('S003', '第13章 発声練習の注意', '{"stop":["声がかすれる","痛みがある","不調が長く続く"],"do_not":["喉が苦しいまま続ける","無理に声を大きくする"],"consult":["症状が続く場合は耳鼻咽喉科等の専門家に相談"],"scope":"発声練習の原稿内注意。個別適用未審査。"}', '{}', ARRAY['P071']::text[]) ON CONFLICT (safety_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_safety (safety_id, title, description, related_catalog_ids, source_passage_ids) VALUES ('S004', '全章の閲覧用実践案に付ける編集上の共通方針', '{"stop":["苦しさ","めまい","胸の痛み","不調の増加"],"do_not":["不調を押して練習を続ける","未記載の保息・秒数を補う"],"consult":["個別の実施可否や症状はこの教材DBだけで判断しない"],"scope":"第2・3・5部の注意から編集した横断方針。全章に同文の記載があるという意味ではない。"}', '{}', ARRAY['P23','P055','P100']::text[]) ON CONFLICT (safety_id) DO NOTHING;